from src.dynamics.minimum_dataset import *

def test_patient_repetition_without_clone_is_insufficient(): assert not selection_identifiable(malignant_identity=True, repeated_samples=True)
def test_clone_without_rna_linkage_is_insufficient(): assert not selection_identifiable(malignant_identity=True, repeated_samples=True, clone_mapping=False, public_mapping=True)
def test_longitudinal_without_malignancy_is_insufficient(): assert not qualify_mechanistic_observability(longitudinal=True, state_representation=True)
def test_longitudinal_malignant_rna_supports_observation(): assert qualify_mechanistic_observability(malignant_identity=True, longitudinal=True, state_representation=True)
def test_clone_is_not_lineage(): assert not plasticity_identifiable(malignant_identity=True, clone_mapping=True, repeated_samples=True, within_clone_state=False, same_cell_lineage=True)
def test_within_clone_difference_is_compatible_with_plasticity(): assert plasticity_identifiable(malignant_identity=True, clone_mapping=True, repeated_samples=True, within_clone_state=True)
def test_frequency_change_is_compatible_with_selection(): assert selection_identifiable(malignant_identity=True, clone_mapping=True, repeated_samples=True, public_mapping=True)
def test_both_require_evidence(): assert not (selection_identifiable(malignant_identity=True, repeated_samples=True) and plasticity_identifiable(malignant_identity=True, repeated_samples=True, within_clone_state=True))
def test_treatment_cannot_define_identity(): assert not qualify_mechanistic_observability(malignant_identity=False, longitudinal=True, state_representation=True, treatment_used=True)
def test_outcome_cannot_define_identity(): assert not qualify_mechanistic_observability(malignant_identity=False, longitudinal=True, state_representation=True, outcome_used=True)
def test_future_data_blocked(): assert not qualify_mechanistic_observability(malignant_identity=True, longitudinal=True, state_representation=True, future_baseline=True)
def test_persistence_is_required_for_gate(): assert not phase5a_eligible(malignant_e4_or_stronger=True)
def test_external_validation_independent(): assert not phase5a_eligible(malignant_e4_or_stronger=True, independent_validation=False)
def test_ordered_phases_are_not_continuous_time(): assert qualify_mechanistic_observability(malignant_identity=True, longitudinal=True, state_representation=True)
def test_valid_tier_a_gate(): assert phase5a_eligible(malignant_e4_or_stronger=True, g1_transport=True, g2_external_prediction=True, g3_treatment_transition=True, partial_clone_state=True, persistence_beaten=True, independent_validation=True, observation_uncertainty=True)
def test_tier_d_not_phase5a(): assert not phase5a_eligible()
def test_missing_clone_blocks_selection(): assert not selection_identifiable(malignant_identity=True, repeated_samples=True, public_mapping=False)
def test_missing_malignancy_blocks_mechanism(): assert not qualify_mechanistic_observability(longitudinal=True, state_representation=True)
